package com.example.custombroadcast; import android.content.Intent; import android.os.Bundle; import android.view.View; import androidx.appcompat.app.AppCompatActivity; public class MainActivity extends AppCompatActivity { public static final String MY_ACTION="com.example.custombroadcast.MY_ACTION"; @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);} public void sendMessage(View v){Intent i=new Intent(MY_ACTION);i.putExtra("message","Hello from MainActivity...");i.setPackage(getPackageName());sendBroadcast(i);}}
